import json
import urllib.error
import urllib.parse
import urllib.request


class GeocodeError(Exception):
    """Raised when the geocoding transport fails."""


def default_get_json(url):
    """Default transport: fetch `url` over HTTP and return parsed JSON."""
    try:
        with urllib.request.urlopen(url, timeout=5) as r:
            return json.load(r)
    except urllib.error.HTTPError as e:
        raise GeocodeError(f"HTTP error fetching {url}: {e}") from e


class Geocoder:
    def __init__(self, get_json=None):
        self.get_json = get_json if get_json is not None else default_get_json

    def lookup(self, address):
        url = "https://geo.example.test/search?q=" + urllib.parse.quote(address)
        try:
            data = self.get_json(url)
        except urllib.error.URLError as e:
            raise GeocodeError(f"transport failure for {url}: {e.reason}") from e
        if not data:
            return None
        best = data[0]
        return {"lat": float(best["lat"]), "lon": float(best["lon"])}

