import socket

import pytest

from geocode import GeocodeError, Geocoder


class FakeTransport:
    """Records requested URLs and serves canned responses."""

    def __init__(self, payload):
        self.payload = payload
        self.urls = []

    def __call__(self, url):
        self.urls.append(url)
        if isinstance(self.payload, Exception):
            raise self.payload
        return self.payload


@pytest.fixture(autouse=True)
def no_sockets():
    real = socket.socket
    socket.socket = None  # type: ignore[assignment]
    yield
    socket.socket = real


def test_spaces_and_unicode_are_percent_encoded():
    fake = FakeTransport([])
    geocoder = Geocoder(get_json=fake)
    geocoder.lookup("Kastanienallee 7 / Hinterhof, München")
    assert fake.urls == [
        "https://geo.example.test/search?q=Kastanienallee%207%20%2F%20Hinterhof%2C%20M%C3%BCnchen"
    ]


def test_first_result_wins():
    fake = FakeTransport(
        [
            {"lat": "52.5200", "lon": "13.4050"},
            {"lat": "48.1372", "lon": "11.5756"},
        ]
    )
    result = Geocoder(get_json=fake).lookup("Berlin")
    assert result == {"lat": 52.52, "lon": 13.405}
    assert len(fake.urls) == 1


def test_empty_payload_returns_none():
    fake = FakeTransport([])
    assert Geocoder(get_json=fake).lookup("nowhere") is None


def test_string_lat_lon_coerced_to_float():
    fake = FakeTransport([{"lat": "-33.86", "lon": "151.21"}])
    result = Geocoder(get_json=fake).lookup("Sydney")
    assert isinstance(result["lat"], float) and isinstance(result["lon"], float)
    assert result == {"lat": -33.86, "lon": 151.21}


def test_urerror_wrapped_as_geocode_error():
    import urllib.error

    fake = FakeTransport(urllib.error.URLError("connection refused"))
    geocoder = Geocoder(get_json=fake)
    with pytest.raises(GeocodeError):
        geocoder.lookup("anything")

